    "s1m.obj.h": "Objetivos de la misión",
    "s1m.obj.p1": "Los principales objetivos de la misión ST3LLARsat1 se formalizan en la tabla siguiente y se comentan a continuación:",
    "s1m.t2.cap": "<strong>Tabla 1.</strong> Principales objetivos de la misión ST3LLARsat1 «Boira»",
    "s1m.t2.h1": "ID del requisito",
    "s1m.t2.h2": "Título",
    "s1m.t2.h3": "Requisito",
    "s1m.t2.r1.t": "Educativo",
    "s1m.t2.r1.d": "Proporcionar a los estudiantes del MISE de la UC3M experiencia práctica en un proyecto espacial real",
    "s1m.t2.r2.t": "Científico",
    "s1m.t2.r2.d": "Monitorizar el cambio climático local midiendo el vapor de agua (WV) atmosférico",
    "s1m.t2.r3.t": "Tecnológico",
    "s1m.t2.r3.d": "Diseñar, construir, lanzar y operar un CubeSat de 2U",
    "s1m.t2.r4.t": "Tecnológico",
